"""Random arrays for maximum subarray sum: a count line, then the values.

At most a dozen values, none past a thousand, so no sum any solution might
form -- correct or not -- can overflow a 32-bit int. An input whose answer
depended on undefined behaviour would have no expected output worth capturing.
"""


def generate(rng, count):
    builders = (_mixed, _all_positive, _all_negative, _two_peaks)
    return [builders[i % len(builders)](rng, i + 1) for i in range(count)]


def _case(name, values, description=""):
    return {
        "name": name,
        "stdin": "%d\n%s\n" % (len(values), " ".join(str(v) for v in values)),
        "description": description,
    }


def _mixed(rng, index):
    values = [rng.randint(-40, 40) for _ in range(rng.randint(6, 11))]
    return _case("mixed values #%d" % index, values)


def _all_positive(rng, index):
    values = [rng.randint(1, 60) for _ in range(rng.randint(4, 8))]
    return _case("all positive #%d" % index, values,
                 "With nothing to lose by carrying on, the best run is the "
                 "whole array.")


def _all_negative(rng, index):
    values = [rng.randint(-90, -1) for _ in range(rng.randint(4, 8))]
    return _case("all negative #%d" % index, values,
                 "At least one element must be chosen, so the answer is the "
                 "largest single value -- not zero.")


def _two_peaks(rng, index):
    """Two good runs with a dip between them, sized so that crossing it is
    sometimes worth it and sometimes is not."""
    left = [rng.randint(3, 30) for _ in range(rng.randint(2, 4))]
    right = [rng.randint(3, 30) for _ in range(rng.randint(2, 4))]
    dip = [-rng.randint(2, 60) for _ in range(rng.randint(1, 2))]
    return _case("two peaks and a dip #%d" % index, left + dip + right,
                 "Whether to cross the dip depends on how deep it is.")
